"""Copies the settings flag helpers of ../../src/main.c (AUTO UNLOAD field, KEF
ITERATIONS steps, flags_with_idle() / flags_with_kef()) into flags_extract.inc,
so test_settings.c checks the firmware's own code (audit IND-H2)."""
SRC = '../../src/main.c'
START = '#define IDLE_DEFAULT_OPTION'
END = 'static uint16_t settings_flags_now(void) {'
text = open(SRC, encoding='utf-8').read().replace('\r\n', '\n')
a = text.index(START)
open('flags_extract.inc', 'w', encoding='utf-8', newline='\n').write(
    '// Generated by extract_flags.py from src/main.c. Do not edit.\n\n' + text[a:text.index(END, a)])
print('wrote flags_extract.inc')
